function cheapestPaint(costs: number[][]): number {
  const go = (i: number, prev: number): number => {
    if (i === costs.length) return 0;
    let best = Infinity;
    for (let c = 0; c < 3; c++) {
      if (c !== prev) best = Math.min(best, costs[i][c] + go(i + 1, c));
    }
    return best;
  };
  return go(0, -1);
}

