function cheapestPaint(costs: number[][]): number {
  let [r, g, b] = costs[0];
  for (let i = 1; i < costs.length; i++) {
    const [cr, cg, cb] = costs[i];
    [r, g, b] = [cr + Math.min(g, b), cg + Math.min(r, b), cb + Math.min(r, g)];
  }
  return Math.min(r, g, b);
}

